                    '0'...'9', 'A'...'F', 'a'...'f' => { p += 1; continue :dfa 76; },
                    else => {},
                };
                break :dfa;
            },
            59 => {
                if (p < n) switch (src[p]) {
                    '=' => { p += 1; self.pos = @intCast(p); return .{ .cat = .@"lshift_assign", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) }; },
                    else => {},
                };
                self.pos = @intCast(p);
                return .{ .cat = .@"lshift", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) };
            },
            65 => {
                if (p < n) switch (src[p]) {
                    '=' => { p += 1; self.pos = @intCast(p); return .{ .cat = .@"rshift_assign", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) }; },
                    else => {},
                };
                self.pos = @intCast(p);
                return .{ .cat = .@"rshift", .pre = pre, .pos = @intCast(start), .len = @intCast(p - start) };
            },
            71 => {
                if (p < n) switch (src[p]) {
                    '+', '-' => { p += 1; continue :dfa 79; },
                    '0'...'9' => { p += 1; continue :dfa 80; },
                    else => {},
                };
                break :dfa;
            },
            72 => {
                while (p < n and src[p] -% '0' <= 1) p += 1;
                self.pos = @intCast(p);
                return makeToken(.@"integer", pre, start, p);
            },
            73 => {
                if (p < n) switch (src[p]) {
                    '0'...'9' => { p += 1; continue :dfa 74; },
                    else => {},
                };
                break :dfa;
            },
            74 => {
                while (p < n and src[p] -% '0' <= 9) p += 1;
                self.pos = @intCast(p);
                return makeToken(.@"real", pre, start, p);
            },
            75 => {
                while (p < n and src[p] -% '0' <= 7) p += 1;
                self.pos = @intCast(p);
                return makeToken(.@"integer", pre, start, p);
            },
            76 => {
                while (p < n and cls4[src[p]]) p += 1;
                self.pos = @intCast(p);
                return makeToken(.@"integer", pre, start, p);
            },
            79 => {
                if (p < n) switch (src[p]) {
                    '0'...'9' => { p += 1; continue :dfa 80; },
                    else => {},
                };
                break :dfa;
            },
            80 => {
                while (p < n and src[p] -% '0' <= 9) p += 1;
                self.pos = @intCast(p);
                return makeToken(.@"real", pre, start, p);
            },
            else => unreachable,
        }
        switch (acc) {
            63 => {
                p = accEnd;
                self.pos = @intCast(p);
                return makeToken(.@"err", pre, start, p);
            },
            12 => {
                p = accEnd;
                self.pos = @intCast(p);
                return makeToken(.@"integer", pre, start, p);
            },
            6 => {
                p = accEnd;
                self.pos = @intCast(p);
                return makeToken(.@"string_sq", pre, start, p);
            },
            10 => {
                p = accEnd;
                self.pos = @intCast(p);
                return makeToken(.@"real", pre, start, p);
            },
            else => {},
        }
        self.pos = @intCast(start + 1);
        return .{ .cat = .@"err", .pre = pre, .pos = @intCast(start), .len = 1 };
    }
};

/// The lexer the parser drives: the lang module's `Lexer` wrapper, if it
/// declares one.
pub const Lexer = if (@hasDecl(lang, "Lexer")) lang.Lexer else BaseLexer;

