        .@"use" => switch (slot) {
            1 => .@"name",
            else => null,
        },
        .@"zig" => switch (slot) {
            1 => .@"code",
            else => null,
        },
        .@"fun" => switch (slot) {
            1 => .@"name",
            2 => .@"params",
            3 => .@"returns",
            4 => .@"body",
            else => null,
